		private static string GetFilter(string asFilter, string adStartDate, string adEndDate, bool abIncldeCheck, int aiOptCheck, int aiSchoolId, int aiAcademicYearId)
		{
			string sFilter = String.Empty;
			asFilter = asFilter != null ? asFilter : String.Empty;
			switch (aiOptCheck)
			{
				case 1:
					sFilter = String.Format(" AND (Enrolment_Number LIKE '%{0}%' OR StudentName LIKE '%{0}%')", StringUtility.ReplaceSingleQuoteInString(asFilter, false));
					break;
				case 2:
					if (adStartDate != String.Empty && adEndDate != String.Empty)
						sFilter = String.Format(" AND PaidDate BETWEEN '{0}' AND '{1}'", adStartDate, adEndDate);
					else if (adStartDate != String.Empty && adEndDate == String.Empty)
						sFilter = String.Format(" AND PaidDate >= '{0}'", adStartDate);
					else if (adStartDate == String.Empty && adEndDate != String.Empty)
						sFilter = String.Format(" AND PaidDate <= '{0}'", adEndDate);
					break;
				case 3:
					if (adStartDate != String.Empty && adEndDate != String.Empty && abIncldeCheck == true)
						sFilter = String.Format(" AND ClearedDate BETWEEN '{0}' AND '{1}'", adStartDate, adEndDate);
					else if (adStartDate != String.Empty && adEndDate == String.Empty && abIncldeCheck == true)
						sFilter = String.Format(" AND ClearedDate >= '{0}'", adStartDate);
					else if (adStartDate == String.Empty && adEndDate != String.Empty && abIncldeCheck == true)
						sFilter = String.Format(" AND ClearedDate <= '{0}'", adEndDate);
					else if ((adStartDate != String.Empty || adEndDate != String.Empty) && abIncldeCheck == false)
						sFilter = " AND ReceiptNo = -9999999";
					break;

			}
			return sFilter;
		}

